   "summary": "科普中国指出新生儿应优先仰卧睡眠降低窒息风险，室温22-26℃、湿度50%-60%；脐带1-2周脱落前保持干燥；生理性黄疸多可自退，若出现24小时内发黄、手脚心发黄、精神差嗜睡需就医；喂奶后竖抱拍嗝防误吸。",
