   "summary": "健康中国科普指出，6月龄内应坚持纯母乳喂养，生后1小时内开奶、回应式喂养；母乳维D含量低，婴儿出生后应每日补充维D 10微克（400IU），无需额外补钙；每月监测身长体重头围。",
