   "summary": "分析指出，2026年政府工作报告强化初婚初育家庭住房保障，十五五规划首次将购房支持写入顶层设计；各地探索差异化路径，如广州一孩家庭公积金贷款额度上浮10%、南充按贷款金额1%贴息、昌吉对二孩及以上家庭发2万元购房消费券。",
