   "summary": "国常会讨论并原则通过《中华人民共和国教师法（修订草案）》和《中华人民共和国价格法（修正草案）》，决定将草案提请全国人大常委会审议。教师法修订强化待遇权益保障、减轻非教育教学负担；价格法修正完善政府定价程序、明确不正当价格行为认定标准。",
