   "summary": "工信部、财政部、发改委发布通知，原则同意京津冀、大湾区、东北（含蒙东）—长三角、新疆—成渝、黄河几字弯—中原等5个城市群试点工作方案，开展氢能综合应用试点工作，试点为期4年。这是落实氢能综合应用试点工作通知的具体落地。",
   "decision": "氢能综合应用试点扩容，长期看或影响能源结构与绿色产业信贷需求，招联可关注绿色金融场景。",
