   "summary": "人民日报评论指出要处理好消费与投资、需求与供给关系，坚持惠民生与促消费结合；以京津冀住院“免备案”等改革为例，强调破除市场壁垒、补上消费短板、稳住内需主动力。",
   "decision": "促消费是政策主线，消费金融是撬动内需的工具之一，招联业务与政策同向。",
