   "summary": "中办、国办印发《文化遗产保护传承“十五五”规划》，文旅部印发文旅发展、旅游强国等专项规划；2025年国内出游65.2亿人次、文化产业营收20.8万亿元，到2030年文旅加快成为支柱产业。",
   "decision": "文旅消费扩容，间接利好消费金融在文旅场景的渗透与分期需求。",
