   "summary": "国务院国资委党委10月14日召开扩大会议，强调着眼增强健康产业核心功能，指导推动有关中央企业做强医药创新、高端医疗装备、公共卫生应急物资保障，加快核心技术攻关和成果转化，并解决央企办医重难点问题，融入各级医疗卫生体系。",
