   "summary": "国务院批复原则同意《国家残疾预防行动计划（2026—2030年）》，要求围绕有效减少和控制残疾发生发展，实施出生缺陷和发育障碍致残源头防控、疾病致残全链条防控、伤害致残重点领域防控、康复服务提升等行动，到2030年残疾预防政策体系和防控网络更加完善。",
