   "summary": "发改委9月30日公告联合财政部完成第四批625亿元超长期特别国债资金下达，全年2500亿元消费品以旧换新补贴全部落地。补贴覆盖汽车、六大类一级能效家电及四类数码智能产品，家电按15%补贴单件上限1500元、数码15%单件上限500元。双11与国补叠加，部分商品低至6.5折。",
