   "summary": "近期北方接连受冷空气影响遭遇同期少见强降雨，大风降温同步进行。预计10月20日至21日新一股冷空气影响我国，西北、华北和东北局地降温10℃至12℃，长江中下游气温迅速下滑；西南、长江中下游及东北局地迎来明显降水，需关注气温变化及时添衣。",
